import React, { useState } from 'react';

function AddRiskForm({ onRiskAdded }) {
  const [form, setForm] = useState({
    category: '',
    description: '',
    score: '',
    status: '',
    date_reported: ''
  });
  const [error, setError] = useState('');

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // ✅ Validation rules
    if (!form.category || !form.description || !form.status || !form.date_reported) {
      setError('All fields are required.');
      return;
    }
    if (isNaN(form.score) || form.score < 1 || form.score > 10) {
      setError('Score must be a number between 1 and 10.');
      return;
    }

    setError('');

    const response = await fetch('http://localhost:5000/api/risks', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form)
    });
    const newRisk = await response.json();
    onRiskAdded(newRisk);
    setForm({ category: '', description: '', score: '', status: '', date_reported: '' });
  };

  return (
    <form onSubmit={handleSubmit}>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <input name="category" placeholder="Category" value={form.category} onChange={handleChange} />
      <input name="description" placeholder="Description" value={form.description} onChange={handleChange} />
      <input name="score" type="number" placeholder="Score (1-10)" value={form.score} onChange={handleChange} />

      {/* ✅ Dropdown for status */}
      <select name="status" value={form.status} onChange={handleChange}>
        <option value="">Select status</option>
        <option value="Open">Open</option>
        <option value="In Progress">In Progress</option>
        <option value="Resolved">Resolved</option>
      </select>

      <input name="date_reported" type="date" value={form.date_reported} onChange={handleChange} />
      <button type="submit">Add Risk</button>
    </form>
  );
}

export default AddRiskForm;
